INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('48afa26259e74e45844a75b6e3bf241d','安钦呼图克图（安钦活佛）',NULL,NULL,NULL,NULL,'','','后藏扎什伦布寺','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：九世班禅麾下重要活佛。抗战期间赴伪满洲国拜见溥仪，出任北平伪 “佛教同愿会” 会长；1939 年掩护日本特务野元甚藏进入西藏，试图为日本打通西藏工作渠道。后态度发生转变，脱离日伪。没有在西藏本地出任伪职，活动主要发生北平、东北西藏文化博...。。结局：国民政府对其警告，后期幡然悔悟，返回西藏，未按汉奸审判','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d136532894084f3288a86d84694a0ded','野元甚藏（野本甚藏）',NULL,NULL,NULL,NULL,'','','日本，关东军特务','[]','["院长", "军长"]','抗日战争时期','汪伪政权','伪任职务：受关东军派遣，跟随安钦活佛入藏；潜伏日喀则，搜集西藏军政、寺院、交通情报，是第一位成功潜入后藏的日本特工。。结局：日本战败后从印度遣返回日本','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('39854f8ee33343c9b50a7581e59cb5c8','木村肥佐生',NULL,NULL,NULL,NULL,'','','日本外务省特务','[]','[]','抗日战争时期','汪伪政权','伪任职务：化名达瓦桑波，伪装蒙古喇嘛，经青海潜入拉萨，搜集西南国际援华通道情报，调查西藏社会民情；日本投降后经亚东逃往印度噶伦堡光明网。。结局：在印度被英军逮捕，遣送回日本，著有《潜伏西藏十年》','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('db714a08b91c48aa85a59abd02d72b57','和加尼牙孜（霍加尼亚孜）',NULL,NULL,NULL,NULL,'','','新疆哈密','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：30 年代哈密暴动领袖；失败后逃亡内地，辗转上海投靠日本特务机关。日本计划利用他返回新疆组建亲日分裂傀儡，接受日方经费，在北平 “哈密公馆” 接受训练，准备伺机潜回新疆。始终未能踏入新疆境内环球网。。结局：日本战败后被国民政府逮捕关押，后病死狱中','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d2c0711fb2704463bd3abb960fe13041','阿齐兹医生',NULL,NULL,NULL,NULL,'','','新疆','[]','["军长", "特务"]','抗日战争时期','汪伪政权','伪任职务：跟随和加尼牙孜流亡上海，与日本陆军特务机关密切合作，为日方做新疆情报翻译，联络流亡的新疆分裂分子，策划渗透新疆。未返回新疆本土活动环球网。。结局：抗战胜利在上海被捕判刑','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('7b4a2bb373a64b60ac2d1017302619c0','铃木住子',NULL,NULL,NULL,NULL,'','','日本','[]','[]','抗日战争时期','汪伪政权','伪任职务：日本女特工，被安排与和加尼牙孜进行政治联姻；担任日特须田正继秘书，专门负责西北新疆方向情报工作，遥控流亡新疆籍人员，本人从未进入新疆境内环球网。。结局：日本投降后遣返回日本','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d19c2223389445ec8f7fe5d6846de8d9','须田正继',NULL,NULL,NULL,NULL,'','','日本陆军特务','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：北平特务机关负责人，专门统筹针对新疆、西北的谍报工作，资助和加尼牙孜流亡集团，策划向新疆派遣潜伏人员。活动基地在北平，没有进入新疆。。结局：日本战败投降，作为战犯被逮捕，后遣返日本','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('948c2c1a3d4241edbe854257b75f1d56','汪精卫',NULL,NULL,NULL,NULL,'','','广东三水','[]','["院长"]','抗日战争时期','汪伪政权','伪任职务：汪伪国民政府主席、行政院院长，在南京建立汪伪政权，签署卖国条约，承认伪满洲国。。结局：1944 年病死于日本名古屋；战后坟墓被炸毁，挫骨扬灰','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
