INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('182275f625b24591a88940cd7944125b','（佚名）',NULL,NULL,NULL,NULL,'','','邵伯','[]','["军长"]','抗日战争时期','汪伪政权','伪任职务：伪邵伯自治会会长（沦陷第一任），1937 年 12 月日军占领邵伯后出面组织维持，强迫商户开业，征派民夫修筑炮楼，协助日军搜刮运河沿线物资。原始报刊史料只记载职务，没有留存完整姓名。。结局：抗战胜利后逮捕判刑','[]','2026-08-26 17:52:47.000000','2026-08-26 17:52:47.000000');
